/**
 * audit-sidecar.ts — the bundled per-indicator licence + rule facts (defect
 * E-23's sidecar, generated by scripts/generate-indicators-registry.ts into
 * data/indicator-audit.json). Two consumers:
 *
 *   - insights-export.ts: the owner-only full export's audit columns
 *     (licenceName, level, ownerAccepts, enabled, ruleVersion, the rule
 *     JSON verbatim).
 *   - the /:id/history route: PUBLIC_BOUNDED_HISTORY_IDS — M-2 (RULES.md
 *     §3): public endpoints serve no bulk history for L2 sources, so ids
 *     whose audit level is L2 while publicDisplayOk is 'yes' (the owner
 *     accepted public display: brent, gold-usd, silver-usd, btc-usd) get
 *     their PUBLIC history bounded to the visible chart window. The list is
 *     DERIVED from the bundled JSON at startup — nothing hard-coded, a
 *     regenerated sidecar updates the bound automatically.
 *
 * Serving is fail-closed at import time: a malformed bundled file throws at
 * startup (a broken repo must never silently open) — the same discipline as
 * public-mode.ts.
 */

import auditJson from '../../../data/indicator-audit.json';
import { z } from 'zod';

const IndicatorAuditEntrySchema = z.object({
  id: z.string().min(1),
  /** The human licence verdict line (level + licence tag). */
  licenceName: z.string(),
  /** The licences.ts register's public-display verdict. */
  publicDisplayOk: z.enum(['yes', 'no', 'unknown']),
  privateOk: z.boolean(),
  /** The v3 source risk level (RULES.md §2). */
  level: z.enum(['L0', 'L1', 'L2', 'L3']),
  /** The owner's recorded acceptance (L2 sources) — never set by the agent. */
  ownerAccepts: z.boolean().nullable(),
  /** M-6: the per-source kill switch. */
  enabled: z.boolean(),
  /** The SCRAPING_SPEC method ladder slot (M1…M5), null for manual composites. */
  method: z.enum(['M1', 'M2', 'M3', 'M4', 'M5']).nullable(),
  maxAgeDays: z.number().nullable(),
  ruleVersion: z.number().int(),
  /** The scoring rule, VERBATIM JSON (never re-serialized on export). */
  rule: z.string(),
});

const IndicatorAuditSchema = z.object({
  $schema: z.string().optional(),
  version: z.number(),
  indicators: z.array(IndicatorAuditEntrySchema).min(1),
});

const parsed = IndicatorAuditSchema.parse(auditJson);

export type IndicatorAuditEntry = z.infer<typeof IndicatorAuditEntrySchema>;

/** Every audit row by indicator id (the export's lookup). */
export const INDICATOR_AUDIT_BY_ID: ReadonlyMap<string, IndicatorAuditEntry> = new Map(
  parsed.indicators.map((entry) => [entry.id, entry]),
);

/**
 * M-2: ids whose public history is bounded to the visible chart window —
 * level L2 (the source restricts display/redistribution, the owner accepted)
 * AND publicDisplayOk 'yes' (the id is actually served publicly; 'no'/'unknown'
 * ids are already hidden entirely by site-mode-overrides.json).
 */
export const PUBLIC_BOUNDED_HISTORY_IDS: ReadonlySet<string> = new Set(
  parsed.indicators.filter((e) => e.level === 'L2' && e.publicDisplayOk === 'yes').map((e) => e.id),
);
